import express from 'express';
import path from 'path';
import fs from 'fs';
import { createServer as createViteServer } from 'vite';
import { CATEGORIES, CARDS_DATA } from './src/data/cardsData';
import { UserProfile, UserStats, CardItem } from './src/types';
import dotenv from 'dotenv';
import { createClient } from '@supabase/supabase-js';

dotenv.config();

const supabaseUrl = process.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = process.env.VITE_SUPABASE_ANON_KEY || '';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

const app = express();
const PORT = 3000;

app.use(express.json());

// In-memory or local JSON database for persistence
const DB_FILE = path.join(process.cwd(), 'users_db.json');

function loadUsers(): Record<string, UserProfile> {
  try {
    if (fs.existsSync(DB_FILE)) {
      const data = fs.readFileSync(DB_FILE, 'utf8');
      return JSON.parse(data);
    }
  } catch (e) {
    console.error('Error loading user DB:', e);
  }
  return {};
}

function saveUsers(users: Record<string, UserProfile>) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(users, null, 2), 'utf8');
  } catch (e) {
    console.error('Error saving user DB:', e);
  }
}

let usersDB: Record<string, UserProfile> = loadUsers();

// Helper to compute user stats & progressive unlock status
function computeUserStats(user: UserProfile): UserStats {
  const normalizedEmail = (user.email || '').trim().toLowerCase();
  const isVIP = normalizedEmail === 'victorsantosv32@gmail.com';

  if (isVIP) {
    const allCategoryIds = CATEGORIES.map(cat => cat.id);
    return {
      user,
      daysElapsed: 7,
      unlockedCategoriesCount: 7,
      unlockedCategoryIds: allCategoryIds,
      nextUnlockDays: 0
    };
  }

  const now = new Date().getTime();
  const created = new Date(user.createdAt).getTime();
  
  // Real calendar days elapsed (Day 1 starts immediately)
  const diffTime = Math.max(0, now - created);
  const realDaysElapsed = Math.floor(diffTime / (1000 * 60 * 60 * 24)) + 1;
  
  // Effective days includes the simulated offset for easy testing
  const effectiveDays = Math.max(1, Math.min(7, realDaysElapsed + (user.simulatedDayOffset || 0)));
  
  // Number of unlocked categories equals effective days (capped at 7)
  const unlockedCategoriesCount = effectiveDays;
  
  const unlockedCategoryIds = CATEGORIES
    .filter(cat => cat.dayNumber <= unlockedCategoriesCount)
    .map(cat => cat.id);
    
  const nextUnlockDays = unlockedCategoriesCount >= 7 ? 0 : 1; // 1 day until next category

  return {
    user,
    daysElapsed: effectiveDays,
    unlockedCategoriesCount,
    unlockedCategoryIds,
    nextUnlockDays
  };
}

// --- API ENDPOINTS ---

// 1. Auth: Login or Register by purchase email
app.post('/api/auth/login', (req, res) => {
  const { email } = req.body;
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    return res.status(400).json({ error: 'Por favor, insira um e-mail de compra válido.' });
  }

  const normalizedEmail = email.trim().toLowerCase();
  
  if (!usersDB[normalizedEmail]) {
    // Create new account with creation date set to NOW
    usersDB[normalizedEmail] = {
      email: normalizedEmail,
      createdAt: new Date().toISOString(),
      simulatedDayOffset: 0,
      favorites: [],
      completedBingo: [],
      status: 'active'
    };
    saveUsers(usersDB);
  }

  const user = usersDB[normalizedEmail];

  if (user.status === 'refunded' || user.status === 'inactive') {
    return res.status(403).json({
      error: 'Acesso desativado ou reembolsado. Se você acredita que isso é um erro, entre em contato com o suporte.'
    });
  }

  const stats = computeUserStats(user);

  res.json({ success: true, stats });
});

// 2. Get current user profile & unlock status
app.get('/api/user/me', (req, res) => {
  const email = req.query.email as string;
  const normalizedEmail = (email || '').trim().toLowerCase();
  if (!normalizedEmail || !usersDB[normalizedEmail]) {
    return res.status(404).json({ error: 'Usuário não encontrado.' });
  }

  const user = usersDB[normalizedEmail];
  if (user.status === 'refunded' || user.status === 'inactive') {
    return res.status(403).json({
      error: 'Acesso desativado ou reembolsado. Se você acredita que isso é um erro, entre em contato com o suporte.'
    });
  }

  const stats = computeUserStats(user);
  res.json(stats);
});

// 3. Simulate Day Offset (Anti-Refund / Testing control)
app.post('/api/user/simulate-days', (req, res) => {
  const { email, dayOffset } = req.body;
  const normalizedEmail = (email || '').trim().toLowerCase();
  
  if (!usersDB[normalizedEmail]) {
    return res.status(404).json({ error: 'Usuário não encontrado.' });
  }

  usersDB[normalizedEmail].simulatedDayOffset = Number(dayOffset) || 0;
  saveUsers(usersDB);

  const stats = computeUserStats(usersDB[normalizedEmail]);
  res.json({ success: true, stats });
});

// 4. Toggle Card Favorite
app.post('/api/user/toggle-favorite', (req, res) => {
  const { email, cardId } = req.body;
  const normalizedEmail = (email || '').trim().toLowerCase();
  const user = usersDB[normalizedEmail];

  if (!user) {
    return res.status(404).json({ error: 'Usuário não encontrado.' });
  }

  if (!user.favorites) user.favorites = [];

  const idx = user.favorites.indexOf(cardId);
  if (idx >= 0) {
    user.favorites.splice(idx, 1);
  } else {
    user.favorites.push(cardId);
  }

  saveUsers(usersDB);
  res.json({ success: true, favorites: user.favorites });
});

// 5. Toggle Bingo Square
app.post('/api/user/toggle-bingo', (req, res) => {
  const { email, index } = req.body;
  const normalizedEmail = (email || '').trim().toLowerCase();
  const user = usersDB[normalizedEmail];

  if (!user) {
    return res.status(404).json({ error: 'Usuário não encontrado.' });
  }

  if (!user.completedBingo) user.completedBingo = [];

  const idx = user.completedBingo.indexOf(index);
  if (idx >= 0) {
    user.completedBingo.splice(idx, 1);
  } else {
    user.completedBingo.push(index);
  }

  saveUsers(usersDB);
  res.json({ success: true, completedBingo: user.completedBingo });
});

// 6. Get Categories & Cards (filtered by unlocked state)
app.get('/api/content/decks', (req, res) => {
  const email = req.query.email as string;
  const normalizedEmail = (email || '').trim().toLowerCase();
  const user = usersDB[normalizedEmail];

  let unlockedCategoryIds: string[] = ['date-night']; // Default Day 1
  if (user) {
    const stats = computeUserStats(user);
    unlockedCategoryIds = stats.unlockedCategoryIds;
  }

  // Map categories with unlocked flag
  const categoriesWithStatus = CATEGORIES.map(cat => ({
    ...cat,
    isUnlocked: unlockedCategoryIds.includes(cat.id),
    daysUntilUnlock: Math.max(0, cat.dayNumber - unlockedCategoryIds.length)
  }));

  // Map cards (for locked categories, hide description and action prompt for anti-refund safety!)
  const cards = CARDS_DATA.map(card => {
    const isUnlocked = unlockedCategoryIds.includes(card.categoryId);
    if (!isUnlocked) {
      return {
        ...card,
        title: `Carta #${card.cardNumber} (Bloqueada)`,
        description: 'Conteúdo exclusivo liberado no dia correspondente de membro.',
        actionPrompt: 'Aguarde a liberação do deck para visualizar esta carta.',
        tag: 'Bloqueado'
      };
    }
    return card;
  });

  res.json({
    categories: categoriesWithStatus,
    cards,
    unlockedCategoryIds
  });
});

// 7. Spin Roulette (Server-authoritative random pick from unlocked decks)
app.post('/api/roulette/spin', (req, res) => {
  const { email, categoryId } = req.body;
  const normalizedEmail = (email || '').trim().toLowerCase();
  const user = usersDB[normalizedEmail];

  let unlockedCategoryIds = ['date-night'];
  if (user) {
    const stats = computeUserStats(user);
    unlockedCategoryIds = stats.unlockedCategoryIds;
  }

  // Filter allowed cards from unlocked categories
  let allowedCards: CardItem[] = [];
  if (categoryId && unlockedCategoryIds.includes(categoryId)) {
    allowedCards = CARDS_DATA.filter(c => c.categoryId === categoryId);
  } else {
    allowedCards = CARDS_DATA.filter(c => unlockedCategoryIds.includes(c.categoryId));
  }

  if (allowedCards.length === 0) {
    allowedCards = CARDS_DATA.filter(c => c.categoryId === 'date-night');
  }

  // Server-side random selection
  const randomIndex = Math.floor(Math.random() * allowedCards.length);
  const selectedCard = allowedCards[randomIndex];
  const category = CATEGORIES.find(cat => cat.id === selectedCard.categoryId);

  res.json({
    card: selectedCard,
    category,
    timestamp: new Date().toISOString()
  });
});

// 8. Cakto Webhook (Ativação automática por venda e desativação por reembolso)
app.post(['/api/webhook/cakto', '/api/cakto/webhook'], async (req, res) => {
  const body = req.body || {};
  console.log('Recebido Webhook Cakto:', JSON.stringify(body));

  // Tenta extrair o e-mail do comprador em várias estruturas de payload enviadas pela Cakto
  let emailRaw: string | undefined = 
    body.customer?.email ||
    body.buyer?.email ||
    body.client?.email ||
    body.email;

  // Se data for um array (como no payload agrupado de múltiplos itens enviado pela Cakto)
  if (!emailRaw && Array.isArray(body.data) && body.data.length > 0) {
    const firstItem = body.data[0];
    emailRaw = 
      firstItem?.customer?.email ||
      firstItem?.buyer?.email ||
      firstItem?.client?.email ||
      firstItem?.email;
  }

  // Se data for um objeto simples
  if (!emailRaw && body.data && !Array.isArray(body.data)) {
    emailRaw = 
      body.data.customer?.email ||
      body.data.buyer?.email ||
      body.data.client?.email ||
      body.data.email;
  }

  if (!emailRaw || typeof emailRaw !== 'string') {
    return res.status(400).json({ error: 'E-mail do comprador não encontrado no payload do webhook.' });
  }

  const normalizedEmail = emailRaw.trim().toLowerCase();

  // Identifica o evento / status (Aprovado / Pago vs Reembolsado / Cancelado)
  let eventStr = String(body.event || body.event_type || body.status || '').toLowerCase();
  
  if (Array.isArray(body.data) && body.data.length > 0) {
    eventStr += ' ' + String(body.data[0]?.status || '').toLowerCase();
  } else if (body.data) {
    eventStr += ' ' + String(body.data.status || '').toLowerCase();
  }

  const isApproved =
    eventStr.includes('approved') ||
    eventStr.includes('paid') ||
    eventStr.includes('pago') ||
    eventStr.includes('aprovad') ||
    eventStr.includes('completed') ||
    eventStr.includes('active');

  const isRefunded =
    eventStr.includes('refund') ||
    eventStr.includes('reembols') ||
    eventStr.includes('chargeback') ||
    eventStr.includes('cancel') ||
    eventStr.includes('devolu') ||
    eventStr.includes('inactive');

  const newStatus = isRefunded ? 'refunded' : 'active';

  try {
    // Buscar se o usuário já existe no Supabase
    const { data: existingUser, error: selectError } = await supabase
      .from('users')
      .select('*')
      .eq('email', normalizedEmail)
      .single();

    if (selectError && selectError.code !== 'PGRST116') {
      console.error('Erro ao buscar usuário no Supabase:', selectError);
      return res.status(500).json({ error: 'Erro no banco de dados do Supabase.' });
    }

    if (!existingUser) {
      // Criar novo usuário no Supabase
      const { error: insertError } = await supabase
        .from('users')
        .insert({
          email: normalizedEmail,
          status: newStatus,
          favorites: [],
          completed_bingo: [],
          simulated_day_offset: 0
        });

      if (insertError) {
        console.error('Erro ao inserir usuário no Supabase:', insertError);
        return res.status(500).json({ error: 'Erro ao criar usuário no Supabase.' });
      }
    } else {
      // Atualizar status do usuário no Supabase
      const { error: updateError } = await supabase
        .from('users')
        .update({ status: newStatus })
        .eq('email', normalizedEmail);

      if (updateError) {
        console.error('Erro ao atualizar status do usuário no Supabase:', updateError);
        return res.status(500).json({ error: 'Erro ao atualizar status no Supabase.' });
      }
    }

    console.log(`[Cakto Webhook Supabase] E-mail: ${normalizedEmail} -> Status: ${newStatus}`);

    // Manter no usersDB local como backup
    if (!usersDB[normalizedEmail]) {
      usersDB[normalizedEmail] = {
        email: normalizedEmail,
        createdAt: new Date().toISOString(),
        simulatedDayOffset: 0,
        favorites: [],
        completedBingo: [],
        status: newStatus
      };
    } else {
      usersDB[normalizedEmail].status = newStatus;
    }
    saveUsers(usersDB);

    return res.json({
      success: true,
      email: normalizedEmail,
      status: newStatus,
      message: `Acesso do cliente ${normalizedEmail} atualizado para ${newStatus} no Supabase.`
    });
  } catch (err) {
    console.error('Erro inesperado no Webhook:', err);
    return res.status(500).json({ error: 'Erro interno no servidor.' });
  }
});

// --- VITE MIDDLEWARE / STATIC SERVING ---
async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa'
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
